using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using Demo6.Game;
public static class V10GuiClick {
 public static async Task<object> Run(){if(!Application.dataPath.Contains("topdown-v10-review-isolated"))throw new Exception("isolated only");var t=typeof(Editor).Assembly.GetType("UnityEditor.GameView");var v=EditorWindow.GetWindow(t);v.Focus();var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;var rows=new List<object>();foreach(string property in new[]{"targetInView","targetInParent"}){if(DungeonUi.Modal!=null)DungeonUi.Close(DungeonUi.Modal);var r=(Rect)t.GetProperty(property,flags).GetValue(v);var source=DungeonHud.UtilityRect(0).center*DungeonUi.Scale;var at=r.position+Vector2.Scale(source,new Vector2(r.width/Screen.width,r.height/Screen.height));v.SendEvent(new Event{type=EventType.MouseDown,mousePosition=at,button=0});await Task.Delay(150);v.SendEvent(new Event{type=EventType.MouseUp,mousePosition=at,button=0});await Task.Delay(300);rows.Add(new{property,at=at.ToString(),modal=DungeonUi.Modal});}return rows;}
}
